from pathlib import Path
import json
from fastapi import FastAPI, HTTPException
from fastapi.responses import HTMLResponse, FileResponse
from fastapi.staticfiles import StaticFiles

ROOT = Path(__file__).resolve().parent
RESULTS = ROOT / "results/results.json"
CIF = ROOT / "data/p53_alphafold_model.cif"
app = FastAPI(title="p53 confidence screen")


def load_results():
    try:
        return json.loads(RESULTS.read_text())
    except Exception as exc:
        raise HTTPException(500, f"Could not read results/results.json: {exc}")


@app.get("/api/results")
def api_results():
    return load_results()


@app.get("/structure.cif")
def structure():
    if not CIF.exists():
        raise HTTPException(404, "Structure file not found")
    return FileResponse(CIF, media_type="chemical/x-mmcif")


@app.get("/", response_class=HTMLResponse)
def index():
    return HTMLResponse(INDEX)


INDEX = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>p53 confidence screen</title><script src="https://cdn.tailwindcss.com"></script>
<script src="https://3Dmol.csb.pitt.edu/build/3Dmol-min.js"></script>
<style>body{background:#f8fafc}.mono{font-variant-numeric:tabular-nums}.viewer{height:560px}.chart{height:330px}</style></head>
<body class="text-slate-900"><main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
<header class="mb-6"><p class="text-sm font-semibold uppercase tracking-widest text-indigo-700">p53 model confidence screen</p><h1 class="mt-2 text-3xl font-bold tracking-tight">A readable, bounded answer for the chemist</h1></header>
<section id="summary" class="relative z-10 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"></section>
<div class="mt-6 grid gap-6 lg:grid-cols-2"><section class="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="mb-3 flex items-center justify-between"><h2 class="text-lg font-semibold">Structure</h2><span class="text-xs text-slate-500">mmCIF · pLDDT from B-factor</span></div><div id="viewer" class="viewer relative z-0 overflow-hidden rounded-xl bg-slate-950"></div><div id="legend" class="mt-3 flex flex-wrap gap-3 text-xs"></div><p class="mt-3 text-sm text-slate-600"><strong>Scope:</strong> residues 18–28 are marked separately and excluded from the shortlist. Residues 293–312 and 183/185 are highlighted as distinct flagged regions.</p><div id="nterm" class="mt-3 rounded-xl bg-violet-50 p-3 text-sm text-violet-950"></div></section>
<section class="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><h2 class="text-lg font-semibold">Confidence matching the claim</h2><p class="mt-1 text-sm text-slate-600">Per-residue local pLDDT across residues 94–312; lower values are weaker assignments.</p><div id="chart" class="chart mt-3"></div><div id="regional" class="mt-4 grid grid-cols-2 gap-3"></div><div id="pae" class="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-900"></div></section></div>
<section class="mt-6 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-lg font-semibold">Interactive region screen</h2><p class="text-sm text-slate-600">Probe the region claim: adjust the threshold or click a residue.</p></div><label class="text-sm font-medium">Cutoff <input id="cutoff" type="range" min="50" max="90" value="70" step="0.01" class="mx-2 align-middle"><output id="cutoffValue">70.00</output></label></div><div id="split" class="mt-3 grid gap-3 sm:grid-cols-2"></div><div class="mt-6 flex items-center justify-between"><h2 class="text-lg font-semibold">Ranked caution / triage list</h2><span id="count" class="text-sm text-slate-500"></span></div><div class="mt-4 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-slate-200 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-3 py-2">Rank</th><th class="px-3 py-2">Residue</th><th class="px-3 py-2">AA</th><th class="px-3 py-2">pLDDT</th><th class="px-3 py-2">Tier</th><th class="px-3 py-2">Region</th></tr></thead><tbody id="table"></tbody></table></div></section>
<section id="caveat" class="mt-6 rounded-2xl border-l-4 border-amber-500 bg-amber-50 p-5 text-amber-950"></section>
<section class="mt-6 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><h2 class="text-lg font-semibold">Scope checks</h2><div id="checks" class="mt-3 grid gap-3 text-sm sm:grid-cols-2"></div></section>
<footer class="mt-8 text-xs text-slate-500">Rendered from <code>results/results.json</code> at request time. Structure served from <code>data/p53_alphafold_model.cif</code>.</footer></main>
<script>
const iconInfo='<svg aria-hidden="true" class="mr-2 inline h-5 w-5 align-text-bottom" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 10v6m0-9h.01"/></svg>';
const iconAlert='<svg aria-hidden="true" class="mr-2 inline h-5 w-5 align-text-bottom" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3 2.5 20h19L12 3Z"/><path d="M12 9v5m0 3h.01"/></svg>';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function band(v,b){return v<50?b[0]:v<70?b[1]:v<90?b[2]:b[3]}
function region(n){return n>=293?'293–312 edge/linker':(n===183||n===185?'DBD isolated hit':'DBD 94–292')}
let selectedResidue=null;let colorMode='raw';function renderChart(d,cutoff=70){const el=document.getElementById('chart'), W=760,H=300,p={l:48,r:16,t:18,b:34};let vals=d.per_residue_plddt_94_312.filter(x=>x.plddt<cutoff);let all=d.per_residue_plddt_94_312.map(x=>({x:x.residue,y:x.plddt}));let min=Math.min(...all.map(x=>x.y)), max=100;let X=x=>p.l+(x-94)/(312-94)*(W-p.l-p.r),Y=y=>p.t+(max-y)/(max-min)*(H-p.t-p.b);let path=all.map((q,i)=>(i?'L':'M')+X(q.x).toFixed(1)+' '+Y(q.y).toFixed(1)).join(' ');let dots=vals.map(q=>`<circle cx="${X(q.residue)}" cy="${Y(q.plddt)}" r="4" fill="#dc2626"/>`).join('');let selected=selectedResidue&&all.find(q=>q.x===selectedResidue);let marker=selected?`<circle cx="${X(selected.x)}" cy="${Y(selected.y)}" r="8" fill="none" stroke="#7c3aed" stroke-width="3"/>`:'';el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" class="h-full w-full" role="img" aria-label="pLDDT across residues 94 to 312"><line x1="${p.l}" x2="${W-p.r}" y1="${Y(70)}" y2="${Y(70)}" stroke="#dc2626" stroke-dasharray="6 4"/><path d="${path}" fill="none" stroke="#334155" stroke-width="2"/>${dots}${marker}<text x="${p.l+5}" y="${Y(70)-6}" font-size="12" fill="#b91c1c">70 cutoff</text><text x="${p.l}" y="${H-8}" font-size="12">94</text><text x="${W-p.r-20}" y="${H-8}" font-size="12">312</text><text x="6" y="${p.t+8}" font-size="12">100</text><text x="12" y="${Y(70)+4}" font-size="12">70</text></svg>`}
function renderViewer(d){let v=$3Dmol.createViewer('viewer',{backgroundColor:'#020617'});window.viewer=v;fetch('/structure.cif').then(r=>r.text()).then(cif=>{v.addModel(cif,'cif');v.setStyle({}, {cartoon:{colorscheme:{prop:'b',gradient:'roygb',min:0,max:100}}});window.applyViewer=()=>{let cutoff=Number(document.getElementById('cutoff').value);let scheme=colorMode==='raw'?{prop:'b',gradient:'roygb',min:0,max:100}:undefined;v.setStyle({}, {cartoon:scheme?{colorscheme:scheme}:{color:'#f59e0b'}});if(colorMode==='bands'){v.setStyle({b:{0:50}},{cartoon:{color:'#ef4444'}});v.setStyle({b:{50:70}},{cartoon:{color:'#f59e0b'}});v.setStyle({b:{70:100}},{cartoon:{color:'#22c55e'}})}v.setStyle({resi:'293-312'},{cartoon:{color:'#ef4444'},stick:{color:'#ef4444'}});v.setStyle({resi:'183,185'},{cartoon:{color:'#f59e0b'},stick:{color:'#f59e0b'}});v.setStyle({resi:'18-28'},{cartoon:{color:'#a855f7'},stick:{color:'#a855f7'}});v.render()};v.setStyle({resi:'293-312'},{cartoon:{color:'#ef4444'},stick:{color:'#ef4444'}});v.setStyle({resi:'183,185'},{cartoon:{color:'#f59e0b'},stick:{color:'#f59e0b'}});v.setStyle({resi:'18-28'},{cartoon:{color:'#a855f7'},stick:{color:'#a855f7'}});v.zoomTo();v.render();});let b=(d.scope&&d.scope.cutoff&&d.scope.cutoff.external_basis)||'<50 very low, 50–<70 low, 70–<90 confident, ≥90 very high';let labels=['<50 very low','50–<70 low','70–<90 confident','≥90 very high'];let colors=['#ff0000','#ff8000','#ffff00','#0000ff'];document.getElementById('legend').innerHTML=labels.map((x,i)=>`<span><i class="mr-1 inline-block h-3 w-3 rounded-full" style="background:${colors[i]}"></i>${esc(x)}</span>`).join('')}
async function main(){let d=await fetch('/api/results').then(r=>r.json());window.screenData=d;let res=d.regional_comparison;let flagged=d.ranked_flagged_residues;document.getElementById('summary').innerHTML=`<div class="flex gap-3">${iconInfo}<div><h2 class="text-lg font-semibold">Headline answer</h2><p class="mt-2 leading-7">The screen found that the folded p53 core is uniformly well modelled. The flagged set is dominated by the tail of the owner’s requested 94–312 range, rather than by problems spread through the fold, so this is a caution/triage list—not a clean target set.</p><p class="mt-3 text-sm font-medium text-slate-700">Structure check: the model sequence matches canonical P04637 residue-for-residue, 393 aa; the file is a monomer, while p53 functions as a tetramer.</p></div></div>`;document.getElementById('regional').innerHTML=['94-292','293-312'].map(k=>`<div class="rounded-xl bg-slate-50 p-3"><div class="text-xs font-semibold text-slate-500">${k}</div><div class="mt-1 text-xl font-bold">min ${k==='94-292'?Math.min(...d.per_residue_plddt_94_312.filter(x=>x.residue<=292).map(x=>x.plddt)).toFixed(2):Math.min(...d.per_residue_plddt_94_312.filter(x=>x.residue>=293).map(x=>x.plddt)).toFixed(2)}</div><div class="text-sm text-slate-600">mean ${res[k].mean_plddt} · ${res[k].below_70_percent}% below 70</div></div>`).join('');let pae=d.pae_relative_placement,pb=pae.blocks;document.getElementById('pae').innerHTML=`${iconAlert}<strong>PAE is not the field for this shortlist.</strong> The file is pairwise relative-placement confidence, ${esc(pae.schema.dimensions)}, in ${esc(pae.schema.units)} &mdash; not per-residue pLDDT, so no row or column of it feeds the ranking above. It does answer one question the ranking cannot: <strong>does 293&ndash;312 sit reliably against the core?</strong> Mean PAE within 94&ndash;292 is <strong>${pb.core_internal_94_292.mean_pae}&nbsp;\u00c5</strong>; from 293&ndash;312 to that core it is <strong>${pb.tail_rows_to_core_columns.mean_pae}&nbsp;\u00c5</strong>, against a declared maximum of ${pae.schema.declared_max}&nbsp;\u00c5. The model does not know where the tail sits.`;document.getElementById('count').textContent=`${d.summary.passing_count} flagged of ${d.summary.core_residues_screened}`;document.getElementById('table').innerHTML=flagged.map(x=>`<tr class="border-b border-slate-100"><td class="px-3 py-2 mono">${x.rank}</td><td class="px-3 py-2 mono">${x.residue}</td><td class="px-3 py-2">${x.amino_acid}</td><td class="px-3 py-2 mono">${x.plddt.toFixed(2)}</td><td class="px-3 py-2"><span class="rounded-full px-2 py-1 text-xs ${x.tier==='very low'?'bg-red-100 text-red-800':'bg-orange-100 text-orange-800'}">${x.tier}</span></td><td class="px-3 py-2">${region(x.residue)}</td></tr>`).join('');let nt=d.n_terminal_18_28_validation_project;document.getElementById('nterm').innerHTML=`<strong>N-terminal 18&ndash;28, the separate validation project.</strong> Excluded from the ranking above, but measured under the identical field and rule: mean pLDDT <strong>${nt.mean_plddt}</strong>, worst <strong>${nt.min_plddt}</strong>, <strong>${nt.below_70_count} of ${nt.count}</strong> residues below 70.00 &mdash; against ${d.regional_comparison['94-292'].mean_plddt} for the folded core. Includes ${nt.mdm2_contact_residues.map(c=>esc(c.amino_acid+c.residue)+' '+c.plddt).join(', ')}. This model does not support 18&ndash;28 as a rigid target; it is not evidence of an MDM2 interface either, being a monomer.`;document.getElementById('caveat').innerHTML=`${iconAlert}<strong>Read this before using the list:</strong> the shortlist is dominated by the 293–312 range boundary rather than problems inside the fold, and the two core hits disappear entirely at a cutoff of 65.`;renderChart(d,70);renderViewer(d);document.getElementById('cutoff').addEventListener('input',e=>{let c=Number(e.target.value);document.getElementById('cutoffValue').textContent=c.toFixed(2);renderChart(d,c);renderDynamic(d,c)});document.getElementById('cutoff').addEventListener('change',()=>window.applyViewer&&window.applyViewer());document.getElementById('viewer').addEventListener('click',()=>{});document.getElementById('checks').innerHTML=`<div class="rounded-xl bg-slate-50 p-3"><strong>Binding:</strong> not applicable to this model claim: one chain means there is no inter-chain PAE block. PAE is ${esc(d.pae_relative_placement.schema.dimensions)} in ${esc(d.pae_relative_placement.schema.units)}.</div><div class="rounded-xl bg-slate-50 p-3"><strong>Mismatch:</strong> no mismatch: model and FASTA match canonical P04637 residue-for-residue, 393 aa, with no overhang and no differing positions.</div>`;renderDynamic(d,70)}function renderDynamic(d,c){let flagged=d.per_residue_plddt_94_312.filter(x=>x.plddt<c);document.getElementById('cutoffValue').textContent=c.toFixed(2);document.getElementById('count').textContent=`${flagged.length} flagged of ${d.summary.core_residues_screened}`;document.getElementById('split').innerHTML=['94-292','293-312'].map(k=>{let a=k==='94-292'?94:293,b=k==='94-292'?292:312,n=flagged.filter(x=>x.residue>=a&&x.residue<=b).length;return `<div class="rounded-xl bg-slate-50 p-3"><strong>${k}</strong><div class="text-2xl font-bold">${n}</div><div class="text-sm text-slate-600">flagged below ${c.toFixed(2)}</div></div>`}).join('');document.getElementById('table').innerHTML=flagged.map((x,i)=>`<tr class="border-b border-slate-100"><td class="px-3 py-2">${i+1}</td><td class="px-3 py-2">${x.residue}</td><td class="px-3 py-2">${x.amino_acid}</td><td class="px-3 py-2">${x.plddt.toFixed(2)}</td><td class="px-3 py-2">${x.plddt<50?'very low':'low'}</td><td class="px-3 py-2">${region(x.residue)}</td></tr>`).join('');renderChart(d,c)}main();
</script></body></html>'''

